from datetime import datetime, timedelta


class Scheduler:
    def __init__(self) -> None:
        self._appointments = {}
        self._next_id = 1

    def book(
        self,
        patient: str,
        doctor: str,
        start: datetime,
        end: datetime,
        now: datetime,
    ) -> int:
        if start >= end:
            raise ValueError("Appointment start must be before its end")
        if start < now:
            raise ValueError("Appointment cannot start in the past")
        if not self.is_free(doctor, start, end):
            raise ValueError("Doctor is not available")

        appointment_id = self._next_id
        self._next_id += 1
        self._appointments[appointment_id] = (patient, doctor, start, end, False)
        return appointment_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        patient, doctor, start, end, cancelled = self._appointments[appointment_id]
        if cancelled:
            return
        if now <= start - timedelta(hours=24):
            del self._appointments[appointment_id]
        else:
            self._appointments[appointment_id] = (patient, doctor, start, end, True)

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        if start >= end:
            raise ValueError("Appointment start must be before its end")
        return not any(
            booked_doctor == doctor and start < booked_end and booked_start < end
            for _, booked_doctor, booked_start, booked_end, _ in self._appointments.values()
        )
